 "content": "def transform(grid):
    # Collapse each consecutive run of identical rows, then columns.
    rows = []
    for row in grid:
        row = list(row)
        if not rows or row != rows[-1]:
            rows.append(row)

    if not rows:
        return []

    keep_cols = []
    for c in range(len(rows[0])):
        col = tuple(row[c] for row in rows)
        if not keep_cols or col != keep_cols[-1]:
            keep_cols.append(col)

    return [[row[c] for c in range(len(keep_cols))] for row in rows]
